'use strict';
const V262={drafts:new Map(),locationNames:{AVAILABLE:'可用',RELEASED:'已释放 / 可用',PLANNED:'已规划锁定',OCCUPIED:'已正式占用',PENDING_REALLOCATION:'存在待重新分配实物',UNAVAILABLE:'不可用'},
 async detail(id){let a=await API.request('/v261/lots/'+id);if(location.pathname!=='/preparation/'+id)return;if(a.workflow_version!=='2.6.1')return this.legacyDetail(id);let busy=false;const editable=Business.can('allocation:write')&&['WORKING','RECTIFY'].includes(a.workflow_state),draft=b=>this.drafts.get(id+':'+b.id)||{},setDraft=(b,key,value)=>{const d={...draft(b)},saved=key==='gross_weight'?(b.final_weighed?Tonnes.format(b.gross_weight):''):(b.seal_valid?b.seal_no||'':'');if(value===saved)delete d[key];else d[key]=value;if(Object.keys(d).length)this.drafts.set(id+':'+b.id,d);else this.drafts.delete(id+':'+b.id);};
 Business.open('备货Lot · '+a.lot_no,`<p>客户 <strong>${esc(a.plan.customer_name)}</strong> · 状态 <strong>${esc(V261.states[a.workflow_state])}</strong> · 规划货位 <strong>${esc(a.planned.code)}</strong></p><p>释放分配不会自动移动实物；主管审核时统一确认规划货位归位。</p><div id="v262-summary" class="v261-summary" aria-live="polite"></div><div class="business-toolbar"><label>明细筛选<select id="v261-filter"><option value="all">全部捆包</option><option value="sample">取样捆包</option><option value="non-sample">非取样捆包</option><option value="unweighed">未完成检斤</option><option value="unsealed">待铅封</option><option value="released">已释放</option></select></label><button type="button" id="v262-refresh" class="button secondary">刷新并核对最新记录</button></div><div id="v261-detail-items"></div>${editable?'<div class="v262-save-bar"><button type="button" id="v262-save-all" class="button primary">一键保存全部检斤</button><span id="v262-dirty" role="status"></span></div>':''}<p id="v261-detail-error" class="error" role="alert"></p><p id="v262-save-status" role="status" aria-live="polite"></p><label>作业 / 审批说明<textarea id="v261-note" maxlength="1000"></textarea></label><div class="business-toolbar">${editable?'<button type="button" id="v261-submit" class="button primary">提交备货审核</button>':''}${editable&&Business.can('lot:cancel-approve')&&![a.created_by,a.submitted_by].includes(CurrentUser.id)?'<button type="button" id="v261-cancel">取消Lot审批</button>':''}${a.workflow_state==='PENDING'&&Business.can('allocation:review')&&![a.created_by,a.submitted_by].includes(CurrentUser.id)?'<label><input type="checkbox" id="v261-stored">确认全部捆包已最终检斤、铅封且完成规划货位归位</label><button type="button" id="v261-approve" class="button primary">主管审核通过</button><button type="button" id="v261-reject">驳回待整改（保留锁定）</button>':''}${a.workflow_state==='PREPARED'&&Business.can('allocation:review')&&![a.created_by,a.submitted_by].includes(CurrentUser.id)?'<button type="button" id="v261-reopen">授权更正（未装车）</button>':''}</div><a href="/stock-map">查看库存地图</a><details id="v262-history"><summary>作业与释放历史</summary><ol>${a.history.map(h=>`<li>${esc(h.bundle_no||a.lot_no)} · ${esc(h.action)} · ${esc(h.actor_name)} · ${esc(h.occurred_at)} · ${esc(h.note)}<pre>${esc(V261.historySummary(h.before_data)+' → '+V261.historySummary(h.after_data))}</pre></li>`).join('')}</ol></details>`);
 const pending=()=>a.items.filter(b=>Object.keys(draft(b)).length),stats=()=>{const q=a.quantities||{},s=a.summary;let gross=0n,net=0n,preview=0,invalid=0;for(const b of a.items){if(b.released_at)continue;const d=draft(b);try{if(d.gross_weight){const n=Tonnes.input(d.gross_weight);gross+=n*100n;net+=(n-25n)*100n;preview++;}else if(b.final_weighed){gross+=Tonnes.scaled(b.gross_weight,6);net+=Tonnes.scaled(b.net_weight,6);preview++;}}catch{invalid++;}}$('v262-summary').innerHTML=`<p>原始 ${q.original_count??s.total} 捆 · 当前有效 ${q.effective_count??s.total} 捆 · 已装车 ${q.loaded_count||0} 捆 · 已正式出库 ${q.outbound_count||0} 捆 · 已释放 ${q.released_count||0} 捆</p><p>总片数 ${q.total_sheets??'未录入'}${q.missing_sheets_count?'（另有 '+q.missing_sheets_count+' 捆未录入）':''} · 已保存检斤 ${s.weighed} / ${s.total} · 已确认铅封 ${a.items.filter(b=>b.seal_valid).length}</p><p>原始备货已知毛重 ${Tonnes.format(q.original_gross)} t / 净重 ${Tonnes.format(q.original_net)} t · 有效分配已知毛重 ${Tonnes.format(q.effective_gross)} t / 净重 ${Tonnes.format(q.effective_net)} t · 已装车净重 ${Tonnes.format(q.loaded_net)} t · 已出库净重 ${Tonnes.format(q.outbound_net)} t</p><p>当前录入预览 ${preview} 捆：毛重 ${preview?Tonnes.format(Tonnes.fixed(gross,6)):'未检斤'} t · 净重 ${preview?Tonnes.format(Tonnes.fixed(net,6)):'未检斤'} t${invalid?' · '+invalid+' 条输入精度或重量无效':''}（含尚未保存输入）</p>`;if($('v262-dirty'))$('v262-dirty').textContent=pending().length+' 捆有未保存修改';};
 const updateRow=b=>{const row=document.querySelector('[data-v262-row="'+b.id+'"]');if(!row)return;const d=draft(b),out=row.querySelector('[data-v261-net]');try{out.textContent=d.gross_weight?Tonnes.fixed(Tonnes.input(d.gross_weight)-25n):b.final_weighed?Tonnes.format(b.net_weight):'待检斤';}catch{out.textContent='输入无效，最多4位小数';}row.querySelector('[data-v262-status]').textContent=b.released_at?'已释放 / 保留历史':!b.final_weighed?'待最终检斤':b.seal_valid?'检斤与铅封完成':'待铅封';};
 const lock=on=>{busy=on;for(const b of document.querySelectorAll('#page-content button'))b.disabled=on;};
 const save=async only=>{if(busy)return;const rows=pending().filter(b=>!only||b.id===only),items=[],sent=new Map();try{for(const b of rows){const d={...draft(b)},changes={};if(Object.hasOwn(d,'gross_weight')){if(d.gross_weight.trim()){Tonnes.input(d.gross_weight);changes.gross_weight=d.gross_weight;}}if(Object.hasOwn(d,'seal_no')){if(!d.seal_no.trim())throw Error(b.bundle_no+'：铅封号不能为空');changes.seal_no=d.seal_no.trim();}if(!Object.keys(changes).length)continue;items.push({bundle_id:b.id,item_version:b.item_version,...changes});sent.set(b.id,d);}if(!items.length){notify('没有可保存的修改，空白毛重保持待检斤');return;}lock(true);$('v261-detail-error').textContent='';const r=await API.request('/v262/lots/'+id+'/weigh',{method:'POST',body:{version:a.version,items,note:$('v261-note').value}});a=r.lot;for(const [bid,d] of sent){const current={...draft({id:bid})};for(const [field,value] of Object.entries(d))if(current[field]===value)delete current[field];if(Object.keys(current).length)this.drafts.set(id+':'+bid,current);else this.drafts.delete(id+':'+bid);const b=a.items.find(b=>b.id===bid);updateRow(b);}stats();$('v262-save-status').textContent='已保存 '+items.length+' 捆。'+(r.warnings||[]).join('；');notify('检斤与铅封已保存');}catch(e){$('v261-detail-error').textContent=e.message+'；未保存输入已保留。';}finally{lock(false);}};
 const action=async(path,body)=>{if(busy)return;lock(true);try{await API.request(path,{method:'POST',body:{version:a.version,...body}});const changed=path.match(/\/items\/([0-9a-f-]{36})\/(sample-mark|sample-stage)$/);if(changed)this.drafts.delete(id+':'+changed[1]);await this.detail(id);}catch(e){$('v261-detail-error').textContent=e.message;lock(false);}};
 const draw=()=>{const f=$('v261-filter').value;const rows=a.items.filter(b=>f==='all'||f==='sample'&&b.sample_required||f==='non-sample'&&!b.sample_required||f==='unweighed'&&!b.final_weighed||f==='unsealed'&&!b.seal_valid||f==='released'&&b.released_at);$('v261-detail-items').innerHTML='<div class="business-table"><table><thead><tr><th>捆包编号 / 批次</th><th>捆包片数</th><th>取样状态</th><th>毛重(t)</th><th>净重(t)</th><th>铅封号（Seal No.）</th><th>检斤及铅封状态</th><th>实际货位</th><th>操作</th></tr></thead><tbody>'+rows.map(b=>{const d=draft(b),can=editable&&!b.released_at&&(!b.sample_required||['RETURNED','WEIGHED'].includes(b.sample_stage));return `<tr data-v262-row="${b.id}"><td><a href="/inventory/${encodeURIComponent(b.bundle_no)}">${esc(b.bundle_no)}</a><br>${esc(b.batch)}</td><td>${b.sheets_per_bundle??'未录入'}</td><td>${esc(V261.sampleStates[b.sample_stage])}${editable&&!b.released_at&&['NOT_REQUIRED','WAITING'].includes(b.sample_stage)?`<label><input type="checkbox" data-v261-mark="${b.id}" ${b.sample_required?'checked':''}>取样</label>`:''}</td><td>${can?`<input data-v261-gross="${b.id}" inputmode="decimal" aria-label="毛重 ${esc(b.bundle_no)}" value="${esc(d.gross_weight??(b.final_weighed?Tonnes.format(b.gross_weight):''))}" placeholder="待检斤">`:b.final_weighed?Tonnes.format(b.gross_weight):'待检斤'}</td><td><output data-v261-net="${b.id}"></output></td><td>${can?`<input data-v262-seal="${b.id}" aria-label="铅封号 ${esc(b.bundle_no)}" maxlength="512" value="${esc(d.seal_no??(b.seal_valid?b.seal_no||'':''))}" placeholder="${esc(b.seal_no?'原铅封 '+b.seal_no+'，需重新确认':'待铅封')}">`:esc(b.seal_no||'未录入')}</td><td data-v262-status></td><td>${esc(b.actual_location)}</td><td>${can?`<button type="button" data-v261-save="${b.id}">保存检斤与铅封</button>`:''}${editable&&!b.released_at&&b.sample_required&&['WAITING','WEIGHED'].includes(b.sample_stage)?`<button type="button" data-v261-stage="${b.id}" data-stage="IN_PROGRESS">${b.sample_stage==='WEIGHED'?'再次取样':'开始取样'}</button>`:''}${editable&&!b.released_at&&b.sample_stage==='IN_PROGRESS'?`<label><input type="checkbox" data-v261-repacked="${b.id}">已返回并重新打包</label><button type="button" data-v261-stage="${b.id}" data-stage="RETURNED">登记返回</button>`:''}</td></tr>`;}).join('')+'</tbody></table></div>';for(const b of rows)updateRow(b);for(const input of document.querySelectorAll('[data-v261-gross],[data-v262-seal]')){const bid=input.dataset.v261Gross||input.dataset.v262Seal;input.oninput=()=>{const b=a.items.find(b=>b.id===bid);setDraft(b,input.dataset.v261Gross?'gross_weight':'seal_no',input.value);updateRow(b);stats();};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();save(bid);}};}for(const b of document.querySelectorAll('[data-v261-save]'))b.onclick=()=>save(b.dataset.v261Save);for(const b of document.querySelectorAll('[data-v261-mark]'))b.onchange=()=>action('/v261/lots/'+id+'/items/'+b.dataset.v261Mark+'/sample-mark',{required:b.checked});for(const b of document.querySelectorAll('[data-v261-stage]'))b.onclick=()=>action('/v261/lots/'+id+'/items/'+b.dataset.v261Stage+'/sample-stage',{stage:b.dataset.stage,repacked:!!document.querySelector('[data-v261-repacked="'+b.dataset.v261Stage+'"]')?.checked});};
 $('v261-filter').onchange=draw;$('v262-refresh').onclick=()=>{if(!busy)this.detail(id).catch(e=>notify(e.message));};if($('v262-save-all'))$('v262-save-all').onclick=()=>save();for(const name of ['submit','approve','reject','reopen'])if($('v261-'+name))$('v261-'+name).onclick=()=>{if(pending().length){$('v261-detail-error').textContent='请先保存当前检斤和铅封修改，再执行业务审批。';return;}action('/v261/lots/'+id+'/'+name,{note:$('v261-note').value,all_weighed_and_stored:!!$('v261-stored')?.checked});};if($('v261-cancel'))$('v261-cancel').onclick=()=>{const why=$('v261-note').value.trim();if(!why){$('v261-detail-error').textContent='请填写取消原因及核实观察说明。';return;}const verified=window.confirm('确认已核实全部捆包的当前真实状态及所在位置？取消将保留所有历史。');if(verified)action('/v261/lots/'+id+'/cancel',{note:why,current_state_verified:true,observation:why});};draw();stats();
 }
};
V262.legacyDetail=V261.detail.bind(V261);V261.detail=V262.detail.bind(V262);
Business.allocationDetail=V261.detail;
V26.weight=v=>Tonnes.format(v);
V262.correctSheets=function(r){Business.open('授权补录 / 更正片数 · '+r.id,`<form id="v262-sheets-form" class="user-form"><p>当前片数 ${r.sheets_per_bundle??'未录入'}。保留原值、修改人、时间和原因；不改写历史装车快照。</p><label>捆包片数<input name="sheets_per_bundle" inputmode="numeric" pattern="[1-9][0-9]*" required value="${r.sheets_per_bundle??''}"></label><label>核实及更正原因<textarea name="reason" required maxlength="1000"></textarea></label><p class="error" id="v262-sheets-error"></p><button class="button primary">保存授权更正</button></form>`);$('v262-sheets-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await API.request('/v262/bundles/'+r.uuid+'/sheets',{method:'PATCH',body:{version:r.version,...Object.fromEntries(new FormData(e.target))}});await Business.bundleDetail(r.id);}catch(err){$('v262-sheets-error').textContent=err.message;e.submitter.disabled=false;}};};
V26.table=items=>`<div class="business-table"><table><thead><tr><th>捆包编号</th><th>生产批次</th><th>捆包片数</th><th>实际货位</th><th>毛重(t)</th><th>净重(t)</th><th>铅封号</th></tr></thead><tbody>${items.map(b=>`<tr><td>${esc(b.bundle_no)}</td><td>${esc(b.batch||'—')}</td><td>${b.sheets_per_bundle??'未录入'}</td><td>${esc(b.location||b.actual_location||b.location_id)}</td><td>${Tonnes.format(b.gross_weight)}</td><td>${Tonnes.format(b.net_weight)}</td><td>${esc(b.seal_no??'未录入')}</td></tr>`).join('')}</tbody></table></div>`;
const v262MapOpen=StockMap.open.bind(StockMap),v262MapDraw=StockMap.draw.bind(StockMap);
StockMap.draw=function(){v262MapDraw();for(const l of this.data.locations){const cell=l.cell_code&&document.querySelector('[data-map-cell="'+l.cell_code+'"]');if(!cell)continue;cell.classList.add('claim-'+l.allocation_state);cell.setAttribute('aria-label',l.code+' '+(V262.locationNames[l.allocation_state]||'')+' '+(l.claim_lot_no||'')+' '+l.current.bundle_count+'捆');}};
StockMap.open=async function(){await v262MapOpen();if(!$('v261-map-planning'))return;const section=document.createElement('section');section.id='v262-location-states';const locations=this.data.locations.filter(l=>['PLANNED','OCCUPIED','PENDING_REALLOCATION','RELEASED'].includes(l.allocation_state));section.innerHTML='<h3>Lot货位独占与实物状态</h3><p>空闲 / 已规划锁定 / 已正式占用 / 待重新分配 / 已释放。释放分配不等于实物已移动。</p><div class="business-table"><table><thead><tr><th>货位</th><th>状态</th><th>关联Lot</th><th>当前普通货位实物</th><th>总片数</th></tr></thead><tbody>'+locations.map(l=>'<tr><td><button type="button" data-v262-location="'+l.id+'">'+esc(l.code)+'</button></td><td>'+esc(V262.locationNames[l.allocation_state])+'</td><td>'+esc(l.claim_lot_no||'—')+'</td><td>'+l.current.bundle_count+'捆</td><td>'+(l.current.total_sheets??'未录入')+'</td></tr>').join('')+'</tbody></table></div>';$('v261-map-planning').before(section);for(const b of section.querySelectorAll('[data-v262-location]'))b.onclick=()=>this.select(b.dataset.v262Location);};

const v262BundleHistory=Business.bundleHistory.bind(Business);Business.bundleHistory=async function(id){await v262BundleHistory(id);const b=await API.request('/bundles/'+encodeURIComponent(id)),h=await API.request('/v262/bundles/'+b.uuid+'/metadata-history');if(!$('page-content'))return;const section=document.createElement('section');section.innerHTML='<h3>片数与铅封历史</h3><ol>'+h.items.map(x=>'<li>'+esc(x.occurred_at)+' · '+esc(x.actor_name)+' · '+esc(x.reason)+'<pre>'+esc(JSON.stringify({before:{sheets:x.before_data?.sheets_per_bundle,seal:x.before_data?.seal_no},after:{sheets:x.after_data?.sheets_per_bundle,seal:x.after_data?.seal_no}}))+'</pre></li>').join('')+'</ol>';$('page-content').append(section);};

V262.correctSeal=function(r){Business.open('授权铅封补录 / 更正 · '+r.id,`<form id="v262-seal-form" class="user-form"><p>仅限已备货且未被装车占用的捆包。必须核实最终检斤及现场铅封，历史装车快照不改写。</p><label>铅封号<input name="seal_no" required maxlength="512" value="${esc(r.seal_no??'')}"></label><label>核实及更正原因<textarea name="reason" required maxlength="1000"></textarea></label><p id="v262-seal-error" class="error"></p><button class="button primary">保存授权铅封更正</button></form>`);$('v262-seal-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const result=await API.request('/v262/bundles/'+r.uuid+'/seal',{method:'PATCH',body:{version:r.version,...Object.fromEntries(new FormData(e.target))}});await Business.bundleDetail(r.id);if(result.warnings?.length)notify(result.warnings.join('；'));}catch(err){$('v262-seal-error').textContent=err.message;e.submitter.disabled=false;}};};
